import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet } from '../../session/session';
import { usePersonDue } from '../rates/due.slot';
import { type Person, shownName, useEditingPerson, usePeople, useSelectedPeople, useShowRetired } from './people';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useColumnShown } from '../columns/columns';

const SORTS = ['added', 'name', 'grade', 'due-total'] as const;
type Sort = (typeof SORTS)[number];

/** What this screen sorts the people list by (`sortBy`; 'added' — list order — when none is set). It belongs
 *  to the screen: other users' screens, the positions and everything that works in list order are unaffected. */
const useSortBy = (): [Sort, (value: Sort) => void] => {
  const [raw, setRaw] = useSearchParam('sortBy', asString);
  return [(SORTS as readonly string[]).includes(raw) ? (raw as Sort) : 'added', (v) => setRaw(v === 'added' ? undefined : v)];
};

/** Names compare as the store compares them: trimmed and lower-cased, then as written. */
const nameKey = (name: string) => name.trim().toLowerCase();
const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

/** The people sorted by the key; equal keys (and 'added') keep list order. A due-total of n/a sorts last. */
function sorted(people: Person[], by: Sort, dueOf: (p: Person) => string): Person[] {
  if (by === 'added') return people;
  const compare = (a: Person, b: Person): number => {
    if (by === 'name') return cmp(nameKey(a.name), nameKey(b.name)) || cmp(a.name, b.name);
    if (by === 'grade') return cmp(a.grade, b.grade);
    const da = Number(dueOf(a));
    const db = Number(dueOf(b));
    const na = Number.isNaN(da);
    const nb = Number.isNaN(db);
    if (na || nb) return Number(na) - Number(nb);
    return da - db;
  };
  return people.map((p, i) => ({ p, i })).sort((x, y) => compare(x.p, y.p) || x.i - y.i).map((x) => x.p);
}

function SortBy() {
  const [by, setBy] = useSortBy();
  return (
    <label>
      Sort by{' '}
      <select data-testid="sort-by" value={by} onChange={(e) => setBy(e.target.value as Sort)}>
        {SORTS.map((s) => (
          <option key={s} value={s}>
            {s}
          </option>
        ))}
      </select>
    </label>
  );
}

// The sheet's people in list order (by their positions, see move.slot.tsx); retired people only while "show retired" is on.
function PeopleList() {
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople(sheet);
  const [showRetired] = useShowRetired();
  const [selected, setSelected] = useSelectedPeople();
  const [sortBy] = useSortBy();
  const dueOf = usePersonDue(sheet);
  const shown = useColumnShown();

  return (
    <>
    <SortBy />
    <table data-testid="people">
      <thead>
        <tr>
          <th />
          <th>Name</th>
          <th>Grade</th>
          {shown('terms') && <th>Terms</th>}
          {shown('contact') && <th>Contact</th>}
          <th>Tags</th>
          <th>Snapshots</th>
          <th>Clashing</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {sorted(people.data ?? [], sortBy, dueOf).filter((p) => showRetired || !p.retired).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td>
              <input
                type="checkbox"
                data-testid="person-select"
                aria-label="Select person"
                checked={selected.includes(p.id)}
                onChange={(e) => setSelected(e.target.checked ? [...selected, p.id] : selected.filter((id) => id !== p.id))}
              />
            </td>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>{shownName(p)}</td>
            <td data-testid="person-grade">{p.grade}</td>
            {shown('terms') && <td data-testid="person-terms">{p.terms ?? ''}</td>}
            {shown('contact') && <td data-testid="person-contact">{p.contact ?? ''}</td>}
            <td data-testid="person-tags">{p.tags.join(', ')}</td>
            <td>
              {p.snapshots.map((n, i) => (
                <div key={i} data-testid="person-snapshot-line">
                  {n.day} {n.dueTotal}
                </div>
              ))}
            </td>
            <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(String(p.id))}>
                Edit
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
    </>
  );
}

export const contribution = HomeMain.fill({ order: 20, Component: PeopleList });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, personActionKey, useLatestPersonAction } from '../people/people';
import { claimsKey } from '../claims/claims';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { useFigure } from '../locale/locale';
import { useColumnShown } from '../columns/columns';

function StatementHead() {
  const shown = useColumnShown();
  if (!shown('statement-count') && !shown('stated-total') && !shown('statement-date')) return null;
  return <th>Statements</th>;
}

// A person's statements: how many were taken, the last one's due-total and date, a line for each still
// standing (oldest first, by date), and the date and button
// that take one (binding their counting claims to their figures now, or as they stood at the end of the
// date given; a blank date takes it now), and the button that cancels the last one
// (a steward only; its claims follow their live figures again). A refused action shows its error until
// the next action on the person is taken.
function PersonStatement({ person }: { person: Person }) {
  const fig = useFigure();
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [asOf, setAsOf] = useState('');
  const queryClient = useQueryClient();

  const take = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`, { user, asOf: date }),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]);
    },
  });

  const cancel = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unstate`, { user }),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]),
  });

  const latest = useLatestPersonAction(sheet, person.id);
  const shown = useColumnShown();

  if (!shown('statement-count') && !shown('stated-total') && !shown('statement-date')) return null;
  return (
    <td>
      {shown('statement-count') && <><span data-testid="person-statement-count">{person.statementCount}</span>{' '}</>}
      {shown('stated-total') && <><span data-testid="person-stated-total">{fig(person.statedTotal ?? '')}</span>{' '}</>}
      {shown('statement-date') && <><span data-testid="person-statement-date">{person.statementDate ?? ''}</span>{' '}</>}
      {person.statements.map((s, i) => (
        <div key={i} data-testid="person-statement-line-line">
          {s.date} {s.dueTotal}
        </div>
      ))}
      <input
        type="date"
        data-testid="person-statement-asof"
        value={asOf}
        onChange={(e) => {
          take.reset();
          setAsOf(e.target.value);
        }}
      />
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          take.reset();
          take.mutate(asOf);
          // The date goes with this statement only: a refused one's never carries into the next.
          setAsOf('');
        }}
      >
        Statement
      </button>{' '}
      <button
        type="button"
        data-testid="person-unstate"
        disabled={cancel.isPending}
        onClick={() => {
          cancel.reset();
          cancel.mutate();
        }}
      >
        Cancel statement
      </button>
      {take.isError && take.submittedAt >= latest && (
        <span data-testid="person-error" role="alert">
          {' '}
          {take.error instanceof HttpError && take.error.reason ? `${take.error.reason}.` : 'The statement was refused.'}
        </span>
      )}
      {cancel.isError && cancel.submittedAt >= latest && (
        <span data-testid="person-error" role="alert">
          {' '}
          {cancel.error instanceof HttpError && cancel.error.reason
            ? `${cancel.error.reason}.`
            : 'The cancelling was refused.'}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 18, Component: StatementHead }),
  PersonColumns.fill({ order: 18, Component: PersonStatement }),
];

